/// Cash-or-nothing call: pays `cash` if S_T > K.
inline double digital_call(double S, double K, double r, double sigma, double T, double cash) {
    double sq = sigma * std::sqrt(T);
    double b = (std::log(S / K) + (r - 0.5 * sigma * sigma) * T) / sq;
    return cash * std::exp(-r * T) * qt::norm_cdf(b);
}

/// Discretely monitored geometric-average Asian call (Kemna-Vorst style closed form)
/// with n_fix equally spaced fixings ending at T.
inline double geometric_asian_call(double S, double K, double r, double sigma, double T, long long n_fix) {
    if (n_fix < 1) {
        throw std::invalid_argument("need at least one fixing");
    }
    long long n = n_fix;
    // mean and variance of the log of the geometric average
    double mu = std::log(S) + (r - 0.5 * (sigma * sigma)) * T * static_cast<double>(qt::iadd(n, 1LL)) / static_cast<double>(qt::imul(2LL, n));
    double var = sigma * sigma * T * static_cast<double>(qt::iadd(n, 1LL)) * static_cast<double>(qt::iadd(qt::imul(2LL, n), 1LL)) / static_cast<double>(qt::imul(qt::imul(6LL, n), n));
    double sd = std::sqrt(var);
    double a = (mu - std::log(K) + var) / sd;
    return std::exp(-r * T) * (std::exp(mu + 0.5 * var) * qt::norm_cdf(a) - K * qt::norm_cdf(a - sd));
}

/// Cox-Ross-Rubinstein binomial price of a European option, summed directly over
/// terminal nodes. Binomial weights are built in log space so 1000+ steps don't overflow.
inline double crr_european(double S, double K, double r, double sigma, double T, long long steps, bool is_call) {
    if (steps < 1) {
        throw std::invalid_argument("steps must be at least 1");
    }
    double dt = T / static_cast<double>(steps);
    double u = std::exp(sigma * std::sqrt(dt));
    double d = 1 / u;
    double p = (std::exp(r * dt) - d) / (u - d);
    if (!(0 < p && p < 1)) {
        throw std::invalid_argument("risk-neutral probability outside (0, 1): reduce the step size");
    }
    double log_p = std::log(p);
    double log_q = std::log1p(-p);
    double total = 0.0;
    double log_choose = 0.0;  // log C(steps, k), updated incrementally
    for (long long k = 0; k < qt::iadd(steps, 1LL); ++k) {
        if (k > 0) {
            log_choose += std::log(qt::iadd(qt::isub(steps, k), 1LL)) - std::log(k);
        }
        double ST = S * std::pow(u, static_cast<double>(k)) * std::pow(d, static_cast<double>(qt::isub(steps, k)));
        double payoff = is_call ? std::max(ST - K, 0.0) : std::max(K - ST, 0.0);
        if (payoff > 0) {
            total += std::exp(log_choose + static_cast<double>(k) * log_p + static_cast<double>(qt::isub(steps, k)) * log_q) * payoff;
        }
    }
    return std::exp(-r * T) * total;
}

